legacyCharacterProfiles.Saturnia = {"personality": "An ancestral model of scholarship for Scribonia; her spellbook manifestation also expresses joy and companionship.", "achievements": "Legendary Zuk’Teuc archmage and demigod identified by Vesperax as Keeper of the Arcane Secrets. Legend Lore reveals her arrival carrying books and maps.", "relationships": "Scribonia models Manifest Mind after her. Vesperax describes her duty to the First God; Ser Kurayami welcomes her in the recovered arrival vision."};
subchannelMap.saturnia = [{label:"Scribonia",article:"scribonia",summary:"The scholar whose Manifest Mind takes Saturnia’s form."},{label:"Memorable Quotes",article:"memorable-quotes",summary:"Words spoken about Saturnia and her manifestation."},{label:"Living Timeline",article:"living-timeline",summary:"Recovered scenes and the arrival revelation."}];
